import{a as e,c as t,d as n,l as r,m as i,p as a,s as o,t as s,u as c}from"./app-emje7bwI.js";var l=JSON.parse(`{"path":"/documentation/quartz-4.x/cron-expressions.html","title":"Cron Expression Reference","lang":"en-US","frontmatter":{"title":"Cron Expression Reference"},"git":{"updatedTime":1790451733000,"contributors":[{"name":"Marko Lahma","username":"","email":"marko.lahma@gmail.com","commits":1},{"name":"Claude Opus 5.5","username":"","email":"noreply@anthropic.com","commits":1}],"changelog":[{"hash":"4a29e014ef1e61227140e96264c49cf64cd3183d","time":1790451733000,"email":"marko.lahma@gmail.com","author":"Marko Lahma","message":"A captured log reaches its column whole on Oracle and SQL Server","coAuthors":[{"name":"Claude Opus 5.5","email":"noreply@anthropic.com"}]}]},"filePathRelative":"documentation/quartz-4.x/cron-expressions.md"}`),u={name:`cron-expressions.md`},d={class:`hint-container caution`},f={class:`hint-container tip`};function p(s,l,u,p,m,h){let g=a(`RouteLink`);return n(),o(`div`,null,[l[26]||=t(`<p>A <code>CronTrigger</code> fires on a schedule written as a cron expression, such as &quot;at 8:00 every Monday through Friday&quot; or &quot;at 1:30 on the last Friday of the month&quot;.</p><h2 id="format" tabindex="-1"><a class="header-anchor" href="#format"><span>Format</span></a></h2><p>A cron expression is 6 or 7 fields separated by white space:</p><table><thead><tr><th><strong>Field Name</strong></th><th><strong>Mandatory</strong></th><th><strong>Allowed Values</strong></th><th><strong>Allowed Special Characters</strong></th></tr></thead><tbody><tr><td>Seconds</td><td>YES</td><td>0-59</td><td>, - * / H</td></tr><tr><td>Minutes</td><td>YES</td><td>0-59</td><td>, - * / H</td></tr><tr><td>Hours</td><td>YES</td><td>0-23</td><td>, - * / H</td></tr><tr><td>Day of month</td><td>YES</td><td>1-31</td><td>, - * ? / L W H</td></tr><tr><td>Month</td><td>YES</td><td>1-12 or JAN-DEC</td><td>, - * / H</td></tr><tr><td>Day of week</td><td>YES</td><td>1-7 or SUN-SAT</td><td>, - * ? / L # H</td></tr><tr><td>Year</td><td>NO</td><td>empty, 1970-2099</td><td>, - * /</td></tr></tbody></table><p>Simple: <code>* * * * ? *</code>. Complex: <code>0/5 14,18,3-39,52 * ? JAN,MAR,SEP MON-FRI 2002-2010</code>.</p><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>Build an expression with <a href="#building-cron-expressions-programmatically"><code>CronExpressionBuilder</code></a>, and check one by <a href="#checking-an-expression">asking Quartz.NET when it fires</a>; only the library agrees with the library. An online generator targets Java Quartz or plain Unix cron and does not know <a href="#h-hash-for-load-distribution"><code>H</code></a> or <a href="#mon-2-is-a-step-through-the-week"><code>MON/2</code></a>, so treat its output as a draft and confirm it here. Five-field Unix output can be read as written — see <a href="#the-unix-five-field-form">The Unix five-field form</a>.</p></div><h2 id="special-characters" tabindex="-1"><a class="header-anchor" href="#special-characters"><span>Special characters</span></a></h2><ul><li><code>*</code> — all values. <code>*</code> in the minute field is every minute.</li><li><code>?</code> — no specific value. Day-of-month and day-of-week only, where it is a synonym for <code>*</code>: the field names no days. Use it to set one day field and not the other: <code>10</code> in day-of-month and <code>?</code> in day-of-week fires on the 10th, whatever the weekday.</li><li><code>-</code> — a range. <code>10-12</code> in the hour field is 10, 11 and 12. A range whose end is below its start wraps: <code>22-2</code> in the hour field is 22, 23, 0, 1 and 2, and <code>FRI-MON</code> is Friday to Monday.</li><li><code>,</code> — a list. <code>MON,WED,FRI</code> in the day-of-week field is Monday, Wednesday and Friday.</li><li><code>/</code> — an increment. <code>0/15</code> in the seconds field is 0, 15, 30 and 45; <code>5/15</code> is 5, 20, 35 and 50. <code>*/n</code> is <code>0/n</code>. <code>1/3</code> in day-of-month is every 3 days starting on the 1st. A day-of-week step may start from a name: <code>MON/2</code> is <code>2/2</code>, Monday, Wednesday and Friday — see <a href="#mon-2-is-a-step-through-the-week"><code>MON/2</code> is a step through the week</a> if the expression came from 3.x.</li><li><code>L</code> — last. Its meaning depends on the field: <ul><li>Day-of-month: the last day of the month — 31 for January, 28 for February in a non-leap year. <code>L-3</code> is three days before the last day: the 28th of a 31-day month. <code>L</code> can be used in a list: <code>1,15,L</code> is the 1st, the 15th and the last day, and <code>L,L-1</code> is the last two days.</li><li>Day-of-week, alone: <code>7</code>, Saturday. After a value: the last such day of the month — <code>6L</code> is the last Friday.</li></ul></li><li><code>W</code> — the weekday (Monday to Friday) nearest the given day, in day-of-month only, and only after a single day, not a range or list. <code>15W</code>: a Saturday 15th fires on Friday the 14th, a Sunday 15th on Monday the 16th, a Tuesday 15th on the 15th. It never crosses into another month: <code>1W</code> on a Saturday 1st fires on Monday the 3rd.</li><li><code>#</code> — the nth weekday of the month, in day-of-week. <code>6#3</code> is the third Friday, <code>2#1</code> the first Monday, <code>4#5</code> the fifth Wednesday. A month without a fifth one does not fire.</li><li><code>@</code> — a macro naming a whole schedule: <code>@daily</code> <em>is</em> the expression. See <a href="#macros">Macros</a>.</li></ul><div class="hint-container tip"><p class="hint-container-title">Tips</p><p><code>L</code> and <code>W</code> combine in day-of-month as <code>LW</code>, the last weekday of the month. It can be in a list (<code>1,15,LW</code>) and take an offset: <code>LW-2</code> finds the last weekday, then subtracts 2.</p></div><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>Characters and the names of months and days are case-insensitive: <code>MON</code> is <code>mon</code>.</p></div><h2 id="forms-the-parser-refuses" tabindex="-1"><a class="header-anchor" href="#forms-the-parser-refuses"><span>Forms the parser refuses</span></a></h2><p>These six shapes parsed on 3.x but meant something other than what they said: a special character was dropped, or a step degenerated. 4.x throws a <code>FormatException</code> whose message gives the expression the author meant.</p><table><thead><tr><th style="text-align:left;">Written</th><th style="text-align:left;">What it used to mean</th><th style="text-align:left;">Write instead</th></tr></thead><tbody><tr><td style="text-align:left;"><code>1-5W</code></td><td style="text-align:left;">the <code>W</code> was dropped, leaving <code>1-5</code></td><td style="text-align:left;"><code>1W,2W,3W,4W,5W</code>, or drop the <code>W</code>. <code>W</code> applies to a single day, not a range or a list</td></tr><tr><td style="text-align:left;"><code>? * L-3</code>, <code>? * LW</code></td><td style="text-align:left;">the suffix was dropped, leaving Saturday</td><td style="text-align:left;"><code>L-3</code> and <code>LW</code> belong to day-of-month. A bare <code>L</code> in day-of-week is still Saturday</td></tr><tr><td style="text-align:left;"><code>MON,FRI#3</code></td><td style="text-align:left;">the third <strong>Monday</strong>; the Friday was never fired</td><td style="text-align:left;">one trigger per day, or drop the <code>#</code>. <code>#</code> applies to the whole field</td></tr><tr><td style="text-align:left;"><code>5C</code>, <code>1C</code></td><td style="text-align:left;"><code>5</code> / <code>1</code> — <code>C</code> (&quot;calendar&quot;) was never implemented</td><td style="text-align:left;"><code>WithCalendarName</code>, which is what a calendar is for</td></tr><tr><td style="text-align:left;"><code>*/0</code>, <code>5/0</code>, <code>0-10/0</code></td><td style="text-align:left;">no step at all</td><td style="text-align:left;"><code>*</code> for every value, or a step of 1 or more</td></tr><tr><td style="text-align:left;"><code>0-10/120</code></td><td style="text-align:left;">an unchecked step; <code>0/120</code> was already rejected</td><td style="text-align:left;">a step inside the field&#39;s range</td></tr></tbody></table>`,13),e(`p`,null,[l[1]||=r(`If a database may hold one of these, audit it before upgrading: `,-1),c(g,{to:`/documentation/quartz-4.x/migration-guide.html#before-you-upgrade`},{default:i(()=>[...l[0]||=[r(`Before you upgrade`,-1)]]),_:1}),l[2]||=r(` has the query.`,-1)]),l[27]||=t(`<h2 id="mon-2-is-a-step-through-the-week" tabindex="-1"><a class="header-anchor" href="#mon-2-is-a-step-through-the-week"><span><code>MON/2</code> is a step through the week</span></a></h2><p>Since 4.1 a textual day-of-week may take a step, and it means what its numeric twin means: <code>MON/2</code> is <code>2/2</code>, Monday, Wednesday and Friday. <code>MON-FRI/2</code> is <code>2-6/2</code>, the same three days. The step runs to Saturday and does not wrap, as after a number.</p>`,2),e(`div`,d,[l[10]||=e(`p`,{class:`hint-container-title`},`An expression carried over from 3.x means something else`,-1),l[11]||=e(`p`,null,[r(`On 3.x, `),e(`code`,null,`MON/2`),r(` meant `),e(`strong`,null,`every second Monday`),r(`, a fortnight. 4.0 rejected it. 4.1 parses it as Monday, Wednesday and Friday: `),e(`strong`,null,`26 fires a year become 156`),r(`, and nothing is logged, because the expression is valid.`)],-1),e(`p`,null,[l[5]||=r(`Audit for it before upgrading (`,-1),c(g,{to:`/documentation/quartz-4.x/migration-guide.html#before-you-upgrade`},{default:i(()=>[...l[3]||=[r(`Before you upgrade`,-1)]]),_:1}),l[6]||=r(` has the query) and rewrite what you find. Every second Monday is `,-1),l[7]||=e(`code`,null,`RecurrenceScheduleBuilder.Create("FREQ=WEEKLY;INTERVAL=2;BYDAY=MO")`,-1),l[8]||=r(`. `,-1),c(g,{to:`/documentation/quartz-4.x/tutorial/recurrencetrigger.html`},{default:i(()=>[...l[4]||=[e(`code`,null,`RecurrenceTrigger`,-1)]]),_:1}),l[9]||=r(` anchors the interval on the trigger's start time, so the fortnight keeps its phase. 3.x counted whole weeks from wherever the search started, so a misfire, a restart, a failover or a dashboard query could move it.`,-1)])]),l[28]||=t(`<p>The step must be a whole number from 1 to 7, as in the numeric spelling. <code>MON/X</code> and <code>SUN/9</code> are rejected; the message says what a step must be and where the fortnight lives now.</p><h2 id="macros" tabindex="-1"><a class="header-anchor" href="#macros"><span>Macros</span></a></h2><p>The <code>@</code> macros are Vixie cron&#39;s, with the same meanings:</p><table><thead><tr><th style="text-align:left;"><strong>Macro</strong></th><th style="text-align:left;"><strong>Expands to</strong></th><th style="text-align:left;"><strong>Meaning</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><code>@yearly</code>, <code>@annually</code></td><td style="text-align:left;"><code>0 0 0 1 1 ?</code></td><td style="text-align:left;">Midnight on 1 January</td></tr><tr><td style="text-align:left;"><code>@monthly</code></td><td style="text-align:left;"><code>0 0 0 1 * ?</code></td><td style="text-align:left;">Midnight on the 1st of every month</td></tr><tr><td style="text-align:left;"><code>@weekly</code></td><td style="text-align:left;"><code>0 0 0 ? * SUN</code></td><td style="text-align:left;">Midnight every Sunday</td></tr><tr><td style="text-align:left;"><code>@daily</code>, <code>@midnight</code></td><td style="text-align:left;"><code>0 0 0 * * ?</code></td><td style="text-align:left;">Midnight every day</td></tr><tr><td style="text-align:left;"><code>@hourly</code></td><td style="text-align:left;"><code>0 0 * * * ?</code></td><td style="text-align:left;">The top of every hour</td></tr></tbody></table><p>A macro needs no dialect and no opt-in. It works wherever an expression string is read: in code, in an XML scheduling file&#39;s <code>&lt;cron-expression&gt;@daily&lt;/cron-expression&gt;</code>, in the dashboard&#39;s expression box and over the HTTP API.</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">ITrigger</span> trigger <span class="token operator">=</span> TriggerBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;nightly&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span><span class="token string">&quot;@daily&quot;</span><span class="token punctuation">)</span> <span class="token comment">// stored, and shown, as &quot;0 0 0 * * ?&quot;</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The expansion is what is stored: a trigger written with <code>@daily</code> reports <code>0 0 0 * * ?</code>.</p><ul><li><code>@reboot</code> is rejected by name: a scheduler has no reboot to fire on, so schedule the work at startup.</li><li>Any other <code>@name</code> is rejected with the list above.</li><li>There is no <code>@every_minute</code> or <code>@every_second</code>: <code>0 * * * * ?</code> is already short, and <a href="#h-hash-for-load-distribution"><code>H</code></a> spreads load deterministically.</li></ul><h2 id="the-unix-five-field-form" tabindex="-1"><a class="header-anchor" href="#the-unix-five-field-form"><span>The Unix five-field form</span></a></h2><p>An expression from a crontab, a Kubernetes <code>CronJob</code> or most online generators has <strong>five</strong> fields: no seconds, and days of the week numbered 0-7 from Sunday instead of 1-7. Quartz reads that form when asked, with <code>CronFormat.Unix</code>:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token comment">// &quot;at 04:30 on Mondays&quot;, written the way crontab writes it</span></span>
<span class="line"><span class="token class-name">CronExpression</span> expression <span class="token operator">=</span> CronExpression<span class="token punctuation">.</span><span class="token function">Parse</span><span class="token punctuation">(</span><span class="token string">&quot;30 4 * * 1&quot;</span><span class="token punctuation">,</span> CronFormat<span class="token punctuation">.</span>Unix<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// ...and held the way Quartz writes it: &quot;0 30 4 ? * MON&quot;</span></span>
<span class="line"><span class="token class-name"><span class="token keyword">string</span></span> canonical <span class="token operator">=</span> expression<span class="token punctuation">.</span>CronExpressionString<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The format only changes how the string is read. Three methods take it — <code>CronExpression.Parse</code>, <code>CronExpression.TryParse</code> and <code>CronScheduleBuilder.Create</code> — and the result is an ordinary <code>CronExpression</code>:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">ITrigger</span> trigger <span class="token operator">=</span> TriggerBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;weekday-report&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithSchedule</span><span class="token punctuation">(</span>CronScheduleBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token string">&quot;15 10 * * 1-5&quot;</span><span class="token punctuation">,</span> CronFormat<span class="token punctuation">.</span>Unix<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// WithCronSchedule has no format overload; compose one when you need its other options</span></span>
<span class="line"><span class="token class-name">ITrigger</span> composed <span class="token operator">=</span> TriggerBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;weekday-report-2&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span>CronExpression<span class="token punctuation">.</span><span class="token function">Parse</span><span class="token punctuation">(</span><span class="token string">&quot;15 10 * * 1-5&quot;</span><span class="token punctuation">,</span> CronFormat<span class="token punctuation">.</span>Unix<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>A time zone composes the same way: <code>CronExpression.Parse(s, CronFormat.Unix).WithTimeZone(tz)</code>.</p><p><a href="https://crontab.guru/" target="_blank" rel="noopener noreferrer">crontab.guru</a> explains a five-field expression field by field. Use it to read the string, then pass the string to <code>CronFormat.Unix</code> rather than translating it by hand.</p><table><thead><tr><th style="text-align:left;"><strong>Crontab</strong></th><th style="text-align:left;"><strong>Read as</strong></th><th style="text-align:left;"><strong>Meaning</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><code>30 4 * * 1</code></td><td style="text-align:left;"><code>0 30 4 ? * MON</code></td><td style="text-align:left;">04:30 every Monday</td></tr><tr><td style="text-align:left;"><code>0 12 1 * *</code></td><td style="text-align:left;"><code>0 0 12 1 * ?</code></td><td style="text-align:left;">Noon on the 1st of every month</td></tr><tr><td style="text-align:left;"><code>* * * * *</code></td><td style="text-align:left;"><code>0 * * * * ?</code></td><td style="text-align:left;">Every minute</td></tr><tr><td style="text-align:left;"><code>15 10 * * 1-5</code></td><td style="text-align:left;"><code>0 15 10 ? * MON-FRI</code></td><td style="text-align:left;">10:15 on weekdays</td></tr><tr><td style="text-align:left;"><code>0 0 * * 0-6</code></td><td style="text-align:left;"><code>0 0 0 * * ?</code></td><td style="text-align:left;">Midnight every day - <code>0-6</code> is the whole week</td></tr><tr><td style="text-align:left;"><code>0 0 * * 5-1</code></td><td style="text-align:left;"><code>0 0 0 ? * FRI-MON</code></td><td style="text-align:left;">Midnight Friday through Monday</td></tr><tr><td style="text-align:left;"><code>0 0 13 * 5</code></td><td style="text-align:left;"><code>0 0 0 13 * FRI</code></td><td style="text-align:left;">The 13th <strong>and</strong> every Friday - both fields name days</td></tr></tbody></table><p>Only two things differ between the dialects:</p><ul><li><strong>Layout</strong>: five fields, minutes first, no seconds and no year.</li><li><strong>Day-of-week numbering</strong>: 0-7, with both 0 and 7 meaning Sunday. <code>1-5</code> is Monday to Friday, as in crontab, and <code>5</code> is Friday, not the Thursday it means in a Quartz expression.</li></ul><p>The grammar is otherwise the same: <code>L</code>, <code>W</code> and <code>#</code> work in the five-field layout, and <code>L</code> alone in day-of-week is still Saturday, since it is not a number.</p><div class="hint-container tip"><p class="hint-container-title"><code>H</code> composes with the Unix form</p><p><code>CronScheduleBuilder.Create(expression, CronFormat.Unix)</code> reads <code>H</code> in the five-field form. It rewrites to the Quartz form first, then hashes on the trigger&#39;s identity: <code>Create(&quot;H 4 * * 1&quot;, CronFormat.Unix)</code> on a trigger identified as <code>nightly</code> becomes <code>0 13 4 ? * MON</code>. <a href="#h-hash-for-load-distribution"><code>ParseWithHash</code></a> and <code>TryParseWithHash</code> take a format beside the hash key and rewrite first too, so <code>ParseWithHash(&quot;H 4 * * 1&quot;, CronFormat.Unix, &quot;nightly&quot;)</code> is the same expression without a trigger. Because the rewrite comes first, an <code>H</code> in a five-field day-of-week is hashed over Quartz&#39;s 1-7, not crontab&#39;s 0-7.</p><p><code>CronExpression.Parse</code> and <code>TryParse</code> take a format but no hash key, so <code>H</code> has nothing to hash. <code>ResolveHash</code> takes a hash key but no format; it returns a string, so it stays Quartz-form only and rejects a five-field expression with the six-field advice. Use <code>ParseWithHash</code> instead.</p></div><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>The expression is <strong>normalised</strong> to the Quartz form, and the original text is lost. <code>CronExpressionString</code>, the dashboard, the HTTP API and <code>QRTZ_CRON_TRIGGERS.CRON_EXPRESSION</code> all show <code>0 30 4 ? * MON</code> for a trigger written as <code>30 4 * * 1</code>. By design: a stored string that parses only under a flag the store does not persist would be a trap, so there is no format column and there will not be one. It is the same trade as the uppercasing that turns <code>mon-fri</code> into <code>MON-FRI</code>.</p><p>So the format is a parse-time argument only. The XML schema, the HTTP API and the dashboard do not take one: a five-field expression is written in C#, not stored. Macros have no such limit.</p></div><p><strong>The format is stated, never detected.</strong> Detecting it from the field count would make a <em>dropped</em> field silent: <code>0 0 12 * * ?</code> without its month field is <code>0 0 12 * ?</code>, a valid crontab line meaning midnight on the 12th, not noon every day. The same digit also names a different day in each dialect. A five-field expression given without a format fails with an error naming the method that reads it.</p><h3 id="an-expression-copied-from-spring" tabindex="-1"><a class="header-anchor" href="#an-expression-copied-from-spring"><span>An expression copied from Spring</span></a></h3><div class="hint-container caution"><p class="hint-container-title">A Spring expression with a numeric day-of-week schedules the wrong day</p><p>Spring&#39;s <code>@Scheduled(cron = …)</code> has <strong>six</strong> fields, seconds first — the shape of a Quartz expression — so Quartz accepts it. But Spring numbers days the Unix way, 0-7 with 0 and 7 both Sunday, where Quartz uses 1-7 from Sunday. Every numeric day reads one day earlier than written, silently, on every Quartz version.</p><table><thead><tr><th style="text-align:left;"><code>@Scheduled(cron = …)</code></th><th style="text-align:left;">Spring fires</th><th style="text-align:left;">Quartz reads it as</th></tr></thead><tbody><tr><td style="text-align:left;"><code>0 0 9 * * 1</code></td><td style="text-align:left;">09:00 on Mondays</td><td style="text-align:left;">09:00 on <strong>Sundays</strong></td></tr><tr><td style="text-align:left;"><code>0 0 9 * * 1-5</code></td><td style="text-align:left;">09:00 Monday to Friday</td><td style="text-align:left;">09:00 <strong>Sunday to Thursday</strong></td></tr><tr><td style="text-align:left;"><code>0 0 9 * * 6</code></td><td style="text-align:left;">09:00 on Saturdays</td><td style="text-align:left;">09:00 on <strong>Fridays</strong></td></tr><tr><td style="text-align:left;"><code>0 0 9 * * MON-FRI</code></td><td style="text-align:left;">09:00 Monday to Friday</td><td style="text-align:left;">09:00 Monday to Friday</td></tr></tbody></table><p><strong>Write the day as a name.</strong> <code>SUN</code> through <code>SAT</code> mean the same day in Spring, crontab and Quartz, so a named expression survives being pasted either way, as the last row shows.</p><p>There is no <code>CronFormat.Spring</code> and no detection of one. The two six-field dialects have the same shape, so the string cannot tell them apart — which is why <a href="#the-unix-five-field-form">the format is stated</a>. A <code>CronFormat.Spring</code> member could be added later without breaking anything; auto-detection never could, because the existing six-field reading is the one schedules depend on.</p></div><h3 id="if-your-expressions-came-from-another-net-cron-library" tabindex="-1"><a class="header-anchor" href="#if-your-expressions-came-from-another-net-cron-library"><span>If your expressions came from another .NET cron library</span></a></h3><p>Cronos and NCrontab expressions parse here, and almost all fire at the same instants. Two differences are silent, because the expression is valid Quartz cron that means something else:</p><ul><li><strong>Day-of-week numbering.</strong> Quartz numbers <code>1-7</code> with Sunday <code>1</code>; those libraries number <code>0-6</code> with Sunday <code>0</code>, and crontab <code>0-7</code> with both ends Sunday. <code>0 0 2 * * 1</code> is 02:00 on <strong>Sunday</strong> here and on <strong>Monday</strong> there — the same issue as <a href="#an-expression-copied-from-spring">a Spring expression</a>, with the same fix: write the day as a name.</li><li><strong>Both day fields restricted.</strong> Quartz fires on the <strong>union</strong> of day-of-month and day-of-week, as crontab does; Cronos takes the intersection. <code>0 0 2 5 * MON</code> is &quot;the 5th, and every Monday&quot; here and &quot;the 5th, if it is a Monday&quot; there. Put <code>?</code> in one of the two fields to say which one applies.</li></ul><p>Searching from <code>2026-08-21T00:00:00Z</code>, against Cronos 0.11.0:</p><table><thead><tr><th style="text-align:left;">Expression</th><th style="text-align:left;">Quartz</th><th style="text-align:left;">Cronos</th><th style="text-align:left;"></th></tr></thead><tbody><tr><td style="text-align:left;"><code>0 0 2 * * MON</code></td><td style="text-align:left;">2026-08-24 02:00</td><td style="text-align:left;">2026-08-24 02:00</td><td style="text-align:left;">same</td></tr><tr><td style="text-align:left;"><code>0 0 7 * * *</code></td><td style="text-align:left;">2026-08-21 07:00</td><td style="text-align:left;">2026-08-21 07:00</td><td style="text-align:left;">same</td></tr><tr><td style="text-align:left;"><code>0 0 */1 * * *</code></td><td style="text-align:left;">2026-08-21 01:00</td><td style="text-align:left;">2026-08-21 01:00</td><td style="text-align:left;">same</td></tr><tr><td style="text-align:left;"><code>0 */15 * * * *</code></td><td style="text-align:left;">2026-08-21 00:15</td><td style="text-align:left;">2026-08-21 00:15</td><td style="text-align:left;">same</td></tr><tr><td style="text-align:left;"><code>0 30 6 * * MON,TUE,WED,THU,FRI</code></td><td style="text-align:left;">2026-08-21 06:30</td><td style="text-align:left;">2026-08-21 06:30</td><td style="text-align:left;">same</td></tr><tr><td style="text-align:left;"><code>0 0 2 * * 1</code></td><td style="text-align:left;">2026-08-23 (<strong>Sunday</strong>)</td><td style="text-align:left;">2026-08-24 (<strong>Monday</strong>)</td><td style="text-align:left;"><strong>differ</strong></td></tr><tr><td style="text-align:left;"><code>0 0 2 5 * MON</code></td><td style="text-align:left;">2026-08-24 (union)</td><td style="text-align:left;">2026-10-05 (intersection)</td><td style="text-align:left;"><strong>differ</strong></td></tr></tbody></table><p>A <strong>five</strong>-field expression from those libraries is read by <code>CronFormat.Unix</code>, which renumbers the days: <code>CronExpression.Parse(&quot;0 2 * * 1&quot;, CronFormat.Unix)</code> is Monday, as its author meant. See <a href="#the-unix-five-field-form">The Unix five-field form</a>.</p>`,30),e(`div`,f,[l[17]||=e(`p`,{class:`hint-container-title`},`Upgrading from 3.x with such an expression in the database`,-1),e(`p`,null,[l[13]||=r(`3.x required `,-1),l[14]||=e(`code`,null,`?`,-1),l[15]||=r(` in exactly one day field, so it rejected an expression with both day fields restricted; 4.0 stores and fires it. The migration guide has an audit for both shapes above: `,-1),c(g,{to:`/documentation/quartz-4.x/migration-guide.html#if-your-expressions-came-from-another-cron-library`},{default:i(()=>[...l[12]||=[r(`If your expressions came from another cron library`,-1)]]),_:1}),l[16]||=r(`.`,-1)])]),l[29]||=t(`<h2 id="h-hash-for-load-distribution" tabindex="-1"><a class="header-anchor" href="#h-hash-for-load-distribution"><span>H (hash) for load distribution</span></a></h2><p><code>H</code> (&quot;hash&quot;) spreads triggers that share an expression. Many triggers on <code>0 0 0 * * ?</code> (midnight daily) all fire at once and cause a resource spike; <code>H</code> in place of a value gives each trigger a different one.</p><p><code>H</code> resolves to a <strong>deterministic</strong> value derived from the trigger&#39;s identity (name and group). It stays the same while the identity does, and differs between triggers.</p><h3 id="syntax" tabindex="-1"><a class="header-anchor" href="#syntax"><span>Syntax</span></a></h3><table><thead><tr><th style="text-align:left;"><strong>Expression</strong></th><th style="text-align:left;"><strong>Meaning</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><code>H</code></td><td style="text-align:left;">Hash value within the full range of the field</td></tr><tr><td style="text-align:left;"><code>H(0-7)</code></td><td style="text-align:left;">Hash value constrained to the range 0 through 7</td></tr><tr><td style="text-align:left;"><code>H/15</code></td><td style="text-align:left;">Hash-derived offset, then repeat every 15 (e.g., 7, 22, 37, 52)</td></tr><tr><td style="text-align:left;"><code>H(0-29)/10</code></td><td style="text-align:left;">Hash-derived offset in 0-29, then repeat every 10 (e.g., 3, 13, 23)</td></tr></tbody></table><ul><li><code>H</code> can appear in a <strong>comma-separated list</strong> with fixed values, e.g. <code>H,30,45</code>.</li><li><code>H</code> is <strong>not</strong> allowed in the Year field, and cannot be combined with <code>L</code>, <code>W</code> or <code>#</code>.</li></ul><h3 id="hash-examples" tabindex="-1"><a class="header-anchor" href="#hash-examples"><span>Hash examples</span></a></h3><table><thead><tr><th style="text-align:left;"><strong>Expression</strong></th><th style="text-align:left;"><strong>Description</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><code>0 H H * * ?</code></td><td style="text-align:left;">Once per day at a hash-derived hour and minute</td></tr><tr><td style="text-align:left;"><code>0 H H(0-7) * * ?</code></td><td style="text-align:left;">Once per day between midnight and 7:59 AM</td></tr><tr><td style="text-align:left;"><code>0 H/15 * * * ?</code></td><td style="text-align:left;">Every 15 minutes, starting from a hash-derived offset</td></tr><tr><td style="text-align:left;"><code>H H H * * ?</code></td><td style="text-align:left;">Once per day at a unique second, minute, and hour</td></tr></tbody></table><h3 id="usage-with-triggerbuilder" tabindex="-1"><a class="header-anchor" href="#usage-with-triggerbuilder"><span>Usage with TriggerBuilder</span></a></h3><p>Through the builder, the trigger identity is the hash seed. You <strong>must</strong> call <code>WithIdentity()</code>, so the hash comes from a stable name rather than a random GUID:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">ITrigger</span> trigger <span class="token operator">=</span> TriggerBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;nightly-cleanup&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span><span class="token string">&quot;0 H H(0-7) * * ?&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Or give an explicit hash key, which needs no trigger identity. The key rides on the <code>CronExpression</code>, and <code>WithCronSchedule</code> takes one directly:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">ITrigger</span> trigger <span class="token operator">=</span> TriggerBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span>CronExpression<span class="token punctuation">.</span><span class="token function">ParseWithHash</span><span class="token punctuation">(</span><span class="token string">&quot;0 H H(0-7) * * ?&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;nightly-cleanup&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>CronExpression.ParseWithHash</code> resolves the expression on its own; <code>CronExpression.TryParseWithHash</code> is the non-throwing form, for a key and expression from outside your control. Both take a <a href="#the-unix-five-field-form"><code>CronFormat</code></a> as their second argument for an expression not written the Quartz way:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">CronExpression</span> expr <span class="token operator">=</span> CronExpression<span class="token punctuation">.</span><span class="token function">ParseWithHash</span><span class="token punctuation">(</span><span class="token string">&quot;0 H H(0-7) * * ?&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;nightly-cleanup&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">Tips</p><p><code>CronExpressionString</code> returns the <strong>resolved</strong> expression (e.g., <code>&quot;0 23 3 * * ?&quot;</code>), with <code>H</code> replaced by its computed value. That resolved form is what is persisted, so it is stable across restarts.</p></div><h2 id="building-cron-expressions-programmatically" tabindex="-1"><a class="header-anchor" href="#building-cron-expressions-programmatically"><span>Building cron expressions programmatically</span></a></h2><p>To build a schedule from user input, such as a scheduling UI with dropdowns, use the fluent <code>CronExpressionBuilder</code> instead of concatenating strings:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">ITrigger</span> trigger <span class="token operator">=</span> TriggerBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;myTrigger&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span>CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">WithSecond</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">WithMinuteIncrements</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">15</span><span class="token punctuation">)</span> <span class="token comment">// every 15 minutes</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">WithHourRange</span><span class="token punctuation">(</span><span class="token number">8</span><span class="token punctuation">,</span> <span class="token number">17</span><span class="token punctuation">)</span>        <span class="token comment">// between 8:00 and 17:59</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">OnWeekdays</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>               <span class="token comment">// &quot;0 0/15 8-17 ? * MON-FRI&quot;</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>WithCronSchedule</code> accepts the builder (or a built <code>CronExpression</code>) directly, so the chain needs no <code>CronScheduleBuilder</code>. From 4.3 it also takes a lambda that configures a fresh builder: <code>WithCronSchedule(cron =&gt; cron.AtTime(new TimeOnly(3, 0)).OnWeekdays())</code>. Call <code>Build()</code> yourself when you want the <code>CronExpression</code> as a value.</p><p>Each field has a single-value, list, range and increment form (e.g. <code>WithHour</code>, <code>WithHours</code>, <code>WithHourRange</code>, <code>WithHourIncrements</code>). <code>AtTime</code> sets the second, minute and hour together from a <code>TimeOnly</code>; add the days beside it:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">AtTime</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">TimeOnly</span><span class="token punctuation">(</span><span class="token number">9</span><span class="token punctuation">,</span> <span class="token number">30</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// &quot;0 30 9 ? * *&quot;</span></span>
<span class="line"></span>
<span class="line">CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">AtTime</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">TimeOnly</span><span class="token punctuation">(</span><span class="token number">9</span><span class="token punctuation">,</span> <span class="token number">30</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithDaysOfWeek</span><span class="token punctuation">(</span>DayOfWeek<span class="token punctuation">.</span>Monday<span class="token punctuation">,</span> DayOfWeek<span class="token punctuation">.</span>Thursday<span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// &quot;0 30 9 ? * MON,THU&quot;</span></span>
<span class="line"></span>
<span class="line">CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">AtTime</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">TimeOnly</span><span class="token punctuation">(</span><span class="token number">9</span><span class="token punctuation">,</span> <span class="token number">30</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithDayOfMonth</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                                              <span class="token comment">// &quot;0 30 9 15 * ?&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Cron resolves to a whole second, so the sub-second part of the <code>TimeOnly</code> is ignored.</p><p><code>Every</code> (4.3) fires on an interval counted on the clock. It writes the interval&#39;s field and every smaller one; the larger fields still say when it runs:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Every</span><span class="token punctuation">(</span>TimeSpan<span class="token punctuation">.</span><span class="token function">FromMinutes</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>         <span class="token comment">// &quot;0 0/10 * ? * *&quot;</span></span>
<span class="line">CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Every</span><span class="token punctuation">(</span>TimeSpan<span class="token punctuation">.</span><span class="token function">FromHours</span><span class="token punctuation">(</span><span class="token number">6</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// &quot;0 0 0/6 ? * *&quot;</span></span>
<span class="line"></span>
<span class="line">CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Every</span><span class="token punctuation">(</span>TimeSpan<span class="token punctuation">.</span><span class="token function">FromMinutes</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithHourRange</span><span class="token punctuation">(</span><span class="token number">8</span><span class="token punctuation">,</span> <span class="token number">17</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">OnWeekdays</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                                                     <span class="token comment">// &quot;0 0/15 8-17 ? * MON-FRI&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th><code>Every</code> takes</th><th>Because</th></tr></thead><tbody><tr><td>1, 2, 3, 4, 5, 6, 10, 12, 15, 20 or 30 seconds or minutes</td><td>they divide the minute or hour evenly</td></tr><tr><td>1, 2, 3, 4, 6, 8 or 12 hours</td><td>they divide the day evenly</td></tr><tr><td>anything else: <code>ArgumentOutOfRangeException</code></td><td>cron has no even form for it; <code>WithSimpleSchedule(interval)</code> counts it from the trigger&#39;s start</td></tr></tbody></table><p><code>Every</code> and <code>AtTime</code> both say when in the day the expression fires, so combining them throws <code>InvalidOperationException</code>.</p><p>The special characters have dedicated methods:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">OnLastDayOfMonth</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                         <span class="token comment">// &quot;* * * L * ?&quot;</span></span>
<span class="line">CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">OnNearestWeekdayOfMonth</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                <span class="token comment">// &quot;* * * 15W * ?&quot;</span></span>
<span class="line">CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">OnNthDayOfWeekOfMonth</span><span class="token punctuation">(</span>DayOfWeek<span class="token punctuation">.</span>Friday<span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &quot;* * * ? * FRI#3&quot;</span></span>
<span class="line">CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">OnLastDayOfWeekOfMonth</span><span class="token punctuation">(</span>DayOfWeek<span class="token punctuation">.</span>Friday<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// &quot;* * * ? * FRIL&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Rules:</p><ul><li>Unconfigured fields default to <code>*</code> (every value).</li><li>Each field can be configured once; configuring it again throws <code>InvalidOperationException</code>.</li><li>The builder uses one day field: it renders the other as <code>?</code> and throws if you configure both. That is the builder&#39;s rule, not cron&#39;s. An expression naming both day fields fires on their union (<code>0 15 10 1,2,3 * MON,FRI</code>) and <code>CronExpression.Parse</code> accepts it, so write that one as text.</li><li>Values are validated against each field&#39;s range as they are set, and <code>Build()</code> returns a validated <code>CronExpression</code>. Use <code>ToString()</code> if you only need the string.</li><li>Days of the week are emitted as names (<code>MON</code>, <code>FRI</code>, ...), so the expression means the same day in cron dialects that number weekdays differently.</li></ul><h2 id="checking-an-expression" tabindex="-1"><a class="header-anchor" href="#checking-an-expression"><span>Checking an expression</span></a></h2><p>Put an expression you were given — by a colleague, an online generator or an old configuration file — through the parser before it reaches a scheduler. <code>CronExpression.TryParse</code> says whether Quartz.NET can read it; <code>GetNextValidTimeAfter</code> says what it means:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token comment">// does Quartz.NET accept it?</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>CronExpression<span class="token punctuation">.</span><span class="token function">TryParse</span><span class="token punctuation">(</span><span class="token string">&quot;0 0/15 8-17 ? * MON-FRI&quot;</span><span class="token punctuation">,</span> <span class="token keyword">out</span> <span class="token class-name">CronExpression<span class="token punctuation">?</span></span> expression<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">ArgumentException</span><span class="token punctuation">(</span><span class="token string">&quot;Quartz.NET cannot read that expression&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// what does it mean? - the next five times it fires, in the expression&#39;s own time zone</span></span>
<span class="line"><span class="token class-name">DateTimeOffset</span> after <span class="token operator">=</span> DateTimeOffset<span class="token punctuation">.</span>UtcNow<span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token class-name"><span class="token keyword">int</span></span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> <span class="token number">5</span><span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token class-name">DateTimeOffset<span class="token punctuation">?</span></span> fireTime <span class="token operator">=</span> expression<span class="token punctuation">.</span><span class="token function">GetNextValidTimeAfter</span><span class="token punctuation">(</span>after<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>fireTime <span class="token keyword">is</span> <span class="token keyword">null</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">break</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    Console<span class="token punctuation">.</span><span class="token function">WriteLine</span><span class="token punctuation">(</span>TimeZoneInfo<span class="token punctuation">.</span><span class="token function">ConvertTime</span><span class="token punctuation">(</span>fireTime<span class="token punctuation">.</span>Value<span class="token punctuation">,</span> expression<span class="token punctuation">.</span>TimeZone<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    after <span class="token operator">=</span> fireTime<span class="token punctuation">.</span>Value<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>A schedule off by a day or an hour looks plausible as a string and obvious as a list of dates. This is also the only check that covers the whole dialect: <a href="#h-hash-for-load-distribution"><code>H</code></a>, a wrapping range (<code>22-2</code>, <code>FRI-MON</code>), <a href="#mon-2-is-a-step-through-the-week"><code>MON/2</code></a> and how the two day fields combine each differ from Java Quartz, Unix cron or both, and no external tool implements them.</p><ul><li><code>GetNextValidTimeAfter</code> returns <code>null</code> when there is no further fire time (for example, an expression naming a past year), so the loop stops.</li><li>The times are <code>DateTimeOffset</code>. <code>TimeZone</code> is the zone the expression is read in (the local zone unless you passed one); converting before printing makes <a href="#daylight-saving-time">daylight saving time</a> visible.</li><li><code>CronExpression.Parse</code> throws instead of returning <code>false</code>. Both take a <a href="#the-unix-five-field-form"><code>CronFormat</code></a>.</li></ul><h2 id="examples" tabindex="-1"><a class="header-anchor" href="#examples"><span>Examples</span></a></h2><table><thead><tr><th style="text-align:left;"><strong>Expression</strong></th><th style="text-align:left;"><strong>Meaning</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><code>0 0 12 * * ?</code></td><td style="text-align:left;">12:00 (noon) every day</td></tr><tr><td style="text-align:left;"><code>0 15 10 ? * *</code></td><td style="text-align:left;">10:15 every day</td></tr><tr><td style="text-align:left;"><code>0 15 10 * * ?</code></td><td style="text-align:left;">10:15 every day</td></tr><tr><td style="text-align:left;"><code>0 15 10 * * ? *</code></td><td style="text-align:left;">10:15 every day</td></tr><tr><td style="text-align:left;"><code>0 15 10 * * ? 2005</code></td><td style="text-align:left;">10:15 every day during 2005</td></tr><tr><td style="text-align:left;"><code>0 * 14 * * ?</code></td><td style="text-align:left;">Every minute from 14:00 to 14:59, every day</td></tr><tr><td style="text-align:left;"><code>0 0/5 14 * * ?</code></td><td style="text-align:left;">Every 5 minutes from 14:00 to 14:55, every day</td></tr><tr><td style="text-align:left;"><code>0 0/5 14,18 * * ?</code></td><td style="text-align:left;">Every 5 minutes from 14:00 to 14:55 and from 18:00 to 18:55, every day</td></tr><tr><td style="text-align:left;"><code>0 0-5 14 * * ?</code></td><td style="text-align:left;">Every minute from 14:00 to 14:05, every day</td></tr><tr><td style="text-align:left;"><code>0 10,44 14 ? 3 WED</code></td><td style="text-align:left;">14:10 and 14:44 every Wednesday in March</td></tr><tr><td style="text-align:left;"><code>0 15 10 ? * MON-FRI</code></td><td style="text-align:left;">10:15 Monday to Friday</td></tr><tr><td style="text-align:left;"><code>0 15 10 15 * ?</code></td><td style="text-align:left;">10:15 on the 15th of every month</td></tr><tr><td style="text-align:left;"><code>0 15 10 L * ?</code></td><td style="text-align:left;">10:15 on the last day of every month</td></tr><tr><td style="text-align:left;"><code>0 15 10 L-2 * ?</code></td><td style="text-align:left;">10:15 two days before the last day of every month</td></tr><tr><td style="text-align:left;"><code>0 15 10 ? * 6L</code></td><td style="text-align:left;">10:15 on the last Friday of every month</td></tr><tr><td style="text-align:left;"><code>0 15 10 ? * 6L 2002-2005</code></td><td style="text-align:left;">10:15 on the last Friday of every month in 2002, 2003, 2004 and 2005</td></tr><tr><td style="text-align:left;"><code>0 15 10 ? * 6#3</code></td><td style="text-align:left;">10:15 on the third Friday of every month</td></tr><tr><td style="text-align:left;"><code>0 0 12 1/5 * ?</code></td><td style="text-align:left;">12:00 every 5 days, starting on the 1st of the month</td></tr><tr><td style="text-align:left;"><code>0 11 11 11 11 ?</code></td><td style="text-align:left;">11:11 every 11 November</td></tr><tr><td style="text-align:left;"><code>0 15 10 1,2,3 * MON,FRI</code></td><td style="text-align:left;">10:15 on the 1st, 2nd and 3rd of the month, and every Monday and Friday</td></tr><tr><td style="text-align:left;"><code>H H H * * ?</code></td><td style="text-align:left;">Once a day at a hash-derived second, minute and hour (spread across triggers)</td></tr><tr><td style="text-align:left;"><code>0 H H(0-7) * * ?</code></td><td style="text-align:left;">Once a day between midnight and 7:59, at a hash-derived time</td></tr><tr><td style="text-align:left;"><code>0 H/15 * * * ?</code></td><td style="text-align:left;">Every 15 minutes, starting from a hash-derived offset</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>Mind <code>?</code> and <code>*</code> in the two day fields. A day field written exactly <code>*</code> or <code>?</code> names no days, so it restricts nothing and the other field decides: <code>0 15 10 1 * *</code> fires on the 1st, and <code>0 15 10 * * MON</code> every Monday. When <strong>both</strong> fields name days, the expression fires on their union, as <code>0 15 10 1,2,3 * MON,FRI</code> above does; when neither does, every day matches. This is the Unix <code>crontab(5)</code> rule. Some other cron implementations intersect the two fields, so an expression copied from one of those fires more often here.</p></div><h2 id="daylight-saving-time" tabindex="-1"><a class="header-anchor" href="#daylight-saving-time"><span>Daylight saving time</span></a></h2><p>A cron expression names a wall-clock time, and a daylight saving transition makes a wall-clock time missing or ambiguous. <strong>Nothing is skipped and nothing fires twice.</strong> Which instant fires depends on whether the expression names a fixed time or an interval.</p><p>A <strong>fixed-time</strong> expression has plain values, or comma lists of plain values, in its second, minute and hour fields — <code>0 30 2 * * ?</code>, <code>0 0,30 2 * * ?</code>:</p><ul><li>A time the clocks <strong>skip</strong> fires once, at the <strong>end of the gap</strong>, the instant the clocks moved. A daily <code>0 30 2 * * ?</code> over a 02:00-03:00 spring-forward gap fires at 03:00. Every wall-clock time in the gap names that instant, so an expression matching several of them still fires once. <code>IsSatisfiedBy</code> agrees with that fire time.</li><li>A time that <strong>occurs twice</strong> on a fall-back day fires once, at the <strong>first</strong> occurrence.</li></ul><p>An <strong>interval</strong> expression has a wildcard, a step or a range in the second, minute or hour field, such as <code>0 * * * * ?</code> or <code>0 0/30 * * * ?</code>. It keeps firing through the repeated hour, so both passes run. Over a spring-forward gap, the gap-end rule shows as an extra fire: <code>0 30 * * * ?</code> fires at 03:00 for the occurrence the gap swallowed and at 03:30 for the next hour&#39;s.</p><p>A <code>CronCalendar</code> written over the skipped hour excludes the gap&#39;s end for the same reason.</p><div class="hint-container warning"><p class="hint-container-title">Quartz 3.x behaves differently</p><p>On 3.x a skipped time is shifted forward by the transition&#39;s delta: the daily <code>0 30 2 * * ?</code> above fires at 03:30, an instant its expression does not match. An interval expression fires the repeated hour only once, so an &quot;every minute&quot; schedule loses an hour of real time each autumn.</p></div>`,46),e(`p`,null,[l[20]||=e(`strong`,null,`Name the time zone.`,-1),l[21]||=r(` An expression with none uses `,-1),l[22]||=e(`code`,null,`TimeZoneInfo.Local`,-1),l[23]||=r(`: the developer's machine in development, and often UTC in a container. `,-1),c(g,{to:`/documentation/best-practices.html#daylight-saving-clock-changes-and-cluster-skew`},{default:i(()=>[...l[18]||=[r(`Daylight saving, clock changes and cluster skew`,-1)]]),_:1}),l[24]||=r(` covers the choice of trigger family, and the `,-1),c(g,{to:`/documentation/faq.html#daylight-saving-time-and-triggers`},{default:i(()=>[...l[19]||=[r(`FAQ`,-1)]]),_:1}),l[25]||=r(` has more.`,-1)])])}var m=s(u,[[`render`,p]]);export{l as _pageData,m as default};